  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 5, 'Descreva posições usando o próprio corpo como referência', 'Para dizer onde algo está à direita ou à esquerda, indique de quem é esse lado. O corpo da pessoa observadora é o referencial; ao virar, ela precisa conferir novamente a relação.', '## Comece por quem observa
Um referencial é o ponto de vista usado para descrever uma posição. Nesta atividade, use o próprio corpo: fique ou imagine-se voltado para uma direção e identifique sua direita, esquerda, frente e atrás. Dizer “a bola está à minha esquerda” informa quem está observando.

## Confira a orientação
Direita e esquerda não são etiquetas fixas dos objetos nem da página. Se você se vira, a relação do mesmo objeto com seu corpo pode mudar. O objeto pode ficar parado enquanto sua orientação muda. Por isso, antes de repetir uma descrição depois de um giro, localize seu corpo e observe de novo.

## Faça uma frase que outra pessoa possa verificar
Nomeie o observador e, quando necessário, para onde ele está olhando: “Para a criança voltada para a porta, o livro está à direita do corpo”. Em um desenho, procure seta, posição do personagem ou outra pista explícita. Se ela não existir, não adivinhe: peça a informação que falta.

## Exemplo resolvido
Lia está olhando para a lousa. A mochila fica ao lado direito do corpo dela. Lia pode dizer: “A mochila está à minha direita”. Depois ela vira para ficar de frente para a turma. A mochila não se moveu, mas Lia deve olhar novamente e descrever o lado em relação ao corpo já virado. Não basta copiar a palavra “direita” da frase anterior.

## Confira em três passos
1. Quem é a pessoa observadora? 2. Para onde o corpo dela está voltado agora? 3. Onde o objeto aparece em relação a esse corpo? Se faltar uma dessas pistas, diga o que ainda precisa ser informado.',
    'Luna olha para uma porta. A mochila está à esquerda do corpo dela. A frase “a mochila está à minha esquerda” é verificável porque identifica Luna como observadora. Quando Luna vira para a janela, a mochila continua parada, mas a relação com o corpo pode mudar; Luna confere novamente antes de falar.', array['Aponte para seu lado antes de escolher direita ou esquerda.', 'Diga de quem é o lado: “à minha direita” ou “à direita da criança”.', 'Depois de virar, observe novamente; não suponha que o objeto se moveu.', 'Se o desenho não informa a orientação, peça uma seta ou descrição.']::text[], 20, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v5-math-spatial-position","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Reconhecer direita e esquerda do próprio corpo com apoio.","Observar posições de objetos próximos.","Compreender as palavras frente e atrás em situações cotidianas."],"key_concepts":["Referencial é a posição de quem observa.","Direita e esquerda em relação ao corpo dependem da orientação do observador.","A posição do objeto pode permanecer enquanto sua relação com o corpo muda.","Uma descrição incompleta deve ser esclarecida, não adivinhada."],"progression":[{"stage":"FOUNDATION","focus":"Nomear o observador e identificar posições simples no próprio corpo.","questionIds":["v5-math-position-probe-01","v5-math-position-probe-02","v5-math-position-probe-03","v5-math-position-practice-01","v5-math-position-practice-02","v5-math-position-practice-03"]},{"stage":"APPLICATION","focus":"Descrever posições e seguir instruções com referencial explícito.","questionIds":["v5-math-position-practice-04","v5-math-position-practice-05","v5-math-position-practice-06","v5-math-position-practice-07","v5-math-position-practice-08"]},{"stage":"INTERMEDIATE","focus":"Atualizar a descrição quando a pessoa vira ou compara orientações.","questionIds":["v5-math-position-practice-09","v5-math-position-practice-10","v5-math-position-practice-11","v5-math-position-transfer-01","v5-math-position-transfer-02"]},{"stage":"ADVANCED_TRANSFER","focus":"Resolver instruções ambíguas em mapas, trajetos e comunicação entre pessoas.","questionIds":["v5-math-position-transfer-03","v5-math-position-transfer-04","v5-math-position-transfer-05","v5-math-position-transfer-06","v5-math-position-transfer-07","v5-math-position-lock-01","v5-math-position-lock-02","v5-math-position-lock-03","v5-math-position-lock-04","v5-math-position-lock-05"]},{"stage":"SPACED_REVIEW_CANDIDATE","focus":"Retomar o referencial em contextos variados e formas de participação acessíveis.","questionIds":["v5-math-position-review-01","v5-math-position-review-02","v5-math-position-review-03","v5-math-position-review-04","v5-math-position-review-05","v5-math-position-review-06","v5-math-position-review-07","v5-math-position-review-08","v5-math-position-review-09"]}],"micro_explanations":[{"trigger":"OBJECT_AS_FIXED_SIDE","text":"O lado não pertence para sempre ao objeto. Diga quem observa e confira para onde essa pessoa está voltada."},{"trigger":"PAGE_AS_BODY","text":"A esquerda da folha só representa a esquerda do corpo se a orientação estiver indicada. Procure uma seta ou peça essa informação."},{"trigger":"OLD_ORIENTATION","text":"Depois de virar, use a orientação atual do corpo. O objeto pode ter ficado parado."},{"trigger":"OBSERVER_MISSING","text":"Antes de responder, pergunte: de quem é a direita ou a esquerda? Sem essa referência, a pista pode ser ambígua."}],"remediations":[{"misconception":"OBJECT_AS_FIXED_SIDE","prompt":"Coloque um objeto de cada lado do corpo. Aponte para a direita, vire-se devagar e observe novamente. Diga uma frase antes e outra depois do giro."},{"misconception":"PAGE_AS_BODY","prompt":"Cubra a resposta e procure no desenho uma seta ou direção do olhar. Se não houver, escreva a pergunta que falta: “para onde a pessoa está voltada?”"},{"misconception":"OLD_ORIENTATION","prompt":"Represente o primeiro ponto de vista com uma seta, faça um quarto de volta e desenhe a nova seta. Só então localize o objeto em relação ao corpo atual."},{"misconception":"OBSERVER_MISSING","prompt":"Reescreva a instrução incluindo quem observa e para onde olha; convide outra pessoa a conferir usando exatamente esse referencial."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"title":"Base Nacional Comum Curricular: Matemática do Ensino Fundamental","publisher":"Ministério da Educação","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","accessedOn":"2026-10-13","supports":["A fonte apresenta a habilidade EF01MA11 sobre descrever localizações em relação à própria posição."],"use":"Dossiê de referência para escopo. O conteúdo é uma proposta interna; o código oficial não foi promovido a mapeamento aprovado e a revisão pedagógica humana continua pendente."}],"copyright_note":"Enunciados, opções, explicações e atividade foram escritos para este pacote. A referência oficial é usada como fonte de escopo, sem copiar itens e sem reivindicar mapeamento oficial aprovado.","authentic_activities":[{"id":"math-spatial-position-classroom-guide","title":"Guia de posições da sala","objective":"Descrever posições de objetos a partir do próprio referencial e verificar como uma mudança de orientação altera a descrição.","context":"A criança cria e testa instruções simples para localizar objetos em uma sala conhecida, usando seu próprio corpo como ponto de referência.","materials":["Dois ou três objetos leves e familiares","Cartões com setas ou folha para desenho","Espaço livre escolhido pelo professor"],"instructions":"Com mediação, escolha objetos que não precisem ser deslocados durante cada observação. Registre onde o observador está e para onde olha; descreva um objeto à direita, à esquerda, à frente ou atrás. Mude a orientação do observador, confira novamente e compare as frases. A criança pode fazer toda a atividade sentada, movendo um marcador que represente sua orientação. Não é necessário tocar em colegas nem vendar os olhos.","evidence":"Duas descrições coerentes com orientações registradas e uma explicação ou demonstração de que a referência mudou, não necessariamente o objeto.","safety":"Use objetos leves, mantenha passagens livres, permita participação sentada e interrompa qualquer movimento desconfortável. Não use vendas, corrida, escadas ou contato físico.","ageRange":"1º ano do Ensino Fundamental; ajustar quantidade de objetos e apoio verbal conforme a necessidade.","mediation":"O adulto registra as pistas oferecidas, pergunta quem observa e verifica se a criança atualiza o referencial. Não atribuir erro quando o desenho ou a orientação estiver ambíguo.","privacyGuard":"Não registrar imagens, vídeos ou dados pessoais das crianças; a evidência pode ser anotada sem identificação nominal.","rubric":[{"criterion":"Identificação do referencial","emerging":"Ainda não indica quem observa, mesmo com apoio.","developing":"Indica o observador após uma pergunta de apoio.","proficient":"Nomeia ou demonstra o próprio corpo como referência antes de descrever."},{"criterion":"Descrição espacial","emerging":"Confunde lados ou não relaciona objeto e corpo.","developing":"Descreve uma posição com apoio e orientação explícita.","proficient":"Produz descrições coerentes com a posição e a orientação observadas."},{"criterion":"Revisão após mudança","emerging":"Mantém a frase sem conferir depois de mudar a orientação.","developing":"Confere novamente com lembrete.","proficient":"Atualiza ou justifica a descrição a partir da nova orientação, reconhecendo quando o objeto não se moveu."}]}],"objective":"Identificar direita, esquerda, frente e atrás em relação à própria posição; explicar como a descrição muda quando o observador muda de orientação; reconhecer quando faltam informações para responder.","common_mistake":"Usar a esquerda da página, de quem lê ou de outra pessoa sem verificar se esse é o referencial indicado; manter a descrição anterior após virar; inventar uma orientação que não aparece no enunciado.","estimated_minutes":20}'::jsonb
  ) on conflict (canonical_skill_id, version) do nothing;
